p.recvuntil(b'[E]xit'); 
res={}
for i in range(-0x40,0x60):
    p.sendline(b'V'); p.recvuntil(b'Index : '); p.sendline(str(i).encode())
    line=p.recvuntil(b'[E]xit') 
    m=re.search(rb'Index (-?\d+) : ([0-9a-f]{2})',line)
    res[i]=m.group(2).decode() if m else None
